float dist_2_point = sqrt(pow((this_texel.x - point_location.x), 2.0 ) + pow((this_texel.y - point_location.y), 2.0 )
+ pow((this_texel.z - point_location.z), 2.0 ));
float point_scale = q11;//.85 - q31;//0.650;
vec3 point_falloff = vec3( 0.0 , 0.0 , 0.0 );
float undispersed = 1.0 - dist_2_point / point_scale;
if (dist_2_point <= point_scale){point_falloff = point_color * undispersed;}
//ret = texture(sampler_main, uv).xyz;
//ret = diffuse;
ret = point_falloff * diffuse;
